+    const sam = { id: 'u-sam', name: 'Sam Ortiz' };
+    expect(archivedText({ by: sam, at: '2026-10-20T21:15:00Z' }, TZ)).toBe(
+      'Archived by Sam Ortiz on Oct 20, 2026',
